import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const menuItems = [
  { path: '/', label: 'Dashboard', icon: '📊' },
  { path: '/route-optimizer', label: 'Route Optimizer', icon: '🗺️' },
  { path: '/resource-assignment', label: 'Resource Assignment', icon: '🚛' },
  { path: '/scheduler', label: 'Scheduler', icon: '📅' },
  { path: '/slot-allocator', label: 'Slot Allocator', icon: '⏰' },
  { path: '/flow-optimizer', label: 'Flow Optimizer', icon: '💧' },
  { path: '/analytics', label: 'Analytics', icon: '📈' },
];

function Sidebar() {
  const [collapsed, setCollapsed] = useState(false);
  const location = useLocation();

  return (
    <aside className={`${collapsed ? 'w-20' : 'w-64'} bg-gradient-to-b from-blue-900 to-blue-800 text-white transition-all duration-300 flex flex-col`}>
      <div className="p-4 flex items-center justify-between">
        {!collapsed && (
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-500 rounded-lg flex items-center justify-center">
              <span className="text-xl">💧</span>
            </div>
            <div>
              <h1 className="font-bold text-lg">Water Tanker</h1>
              <p className="text-xs text-blue-200">Karachi System</p>
            </div>
          </div>
        )}
        <button
          onClick={() => setCollapsed(!collapsed)}
          className="p-2 hover:bg-blue-700 rounded-lg transition-colors"
        >
          {collapsed ? '→' : '←'}
        </button>
      </div>

      <nav className="flex-1 p-4 space-y-2">
        {menuItems.map((item) => (
          <Link
            key={item.path}
            to={item.path}
            className={`flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
              location.pathname === item.path
                ? 'bg-blue-600 shadow-lg'
                : 'hover:bg-blue-700/50'
            }`}
          >
            <span className="text-xl">{item.icon}</span>
            {!collapsed && <span className="font-medium">{item.label}</span>}
          </Link>
        ))}
      </nav>

      <div className="p-4 border-t border-blue-700">
        {!collapsed && (
          <div className="text-xs text-blue-200 text-center">
            <p>DAA Semester Project</p>
            <p className="mt-1">Water Distribution Optimization</p>
          </div>
        )}
      </div>
    </aside>
  );
}

export default Sidebar;
