import React, { useState, useEffect } from 'react';

const API_BASE = 'http://localhost:5000/api';

function SlotAllocator() {
  const [sources, setSources] = useState([]);
  const [tankers, setTankers] = useState([]);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [sourcesRes, tankersRes] = await Promise.all([
        fetch(`${API_BASE}/sources`),
        fetch(`${API_BASE}/tankers`)
      ]);
      const [sourcesData, tankersData] = await Promise.all([
        sourcesRes.json(),
        tankersRes.json()
      ]);
      setSources(sourcesData);
      setTankers(tankersData);
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  const runBacktracking = async () => {
    setLoading(true);
    try {
      const sampleRequests = tankers.slice(0, 8).map((tanker, idx) => ({
        tankerId: tanker.tankerId,
        preferredSource: sources[idx % sources.length].sourceId,
        requestedHour: 8 + Math.floor(Math.random() * 8),
        priority: ['critical', 'high', 'medium', 'low'][Math.floor(Math.random() * 4)],
        loadingDuration: 1
      }));

      const response = await fetch(`${API_BASE}/algorithms/backtrack`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sources: sources,
          tankers: sampleRequests,
          timeSlots: 14,
          options: { maxIterations: 5000 }
        })
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Error running backtracking:', err);
    }
    setLoading(false);
  };

  const hours = Array.from({ length: 14 }, (_, i) => 6 + i);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-800">Slot Allocator</h1>
        <p className="text-gray-600 mt-1">Backtracking for Contention Resolution</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-800">Hydrant Slot Allocation</h3>
            <button
              onClick={runBacktracking}
              disabled={loading}
              className="btn-success disabled:opacity-50"
            >
              {loading ? 'Resolving...' : 'Resolve Conflicts'}
            </button>
          </div>

          <div className="overflow-x-auto">
            <div className="min-w-[700px]">
              <div className="grid grid-cols-[140px_repeat(14,1fr)] gap-1">
                <div className="p-2 text-xs font-medium text-gray-500">Source</div>
                {hours.map(hour => (
                  <div key={hour} className="p-2 text-xs font-medium text-gray-500 text-center">
                    {hour}:00
                  </div>
                ))}

                {sources.slice(0, 5).map(source => (
                  <React.Fragment key={source.sourceId}>
                    <div className="p-2 text-xs font-medium text-gray-700 truncate">
                      {source.name.split(' ').slice(0, 2).join(' ')}
                    </div>
                    {hours.map(hour => {
                      const isOccupied = result?.slotMap?.[source.sourceId]?.[hour] &&
                        !result.slotMap[source.sourceId][hour].available;
                      return (
                        <div
                          key={hour}
                          className={`p-1 rounded text-xs text-center ${
                            isOccupied
                              ? 'bg-red-200 text-red-800'
                              : 'bg-green-100 text-green-700'
                          }`}
                        >
                          {isOccupied ? 'X' : 'O'}
                        </div>
                      );
                    })}
                  </React.Fragment>
                ))}
              </div>
              <div className="flex gap-4 mt-4 text-xs">
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 bg-green-100 rounded"></div>
                  <span>Available</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 bg-red-200 rounded"></div>
                  <span>Occupied</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Water Sources</h3>
          <div className="space-y-3 max-h-64 overflow-y-auto">
            {sources.map(source => (
              <div key={source.sourceId} className="p-3 bg-gray-50 rounded-lg">
                <p className="font-medium text-sm">{source.name}</p>
                <p className="text-xs text-gray-500">Type: {source.type}</p>
                <p className="text-xs text-gray-500">
                  Capacity: {source.capacity.toLocaleString()} L
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {result && (
        <div className="space-y-6">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="stat-card">
              <p className="text-sm text-gray-600">Assigned</p>
              <p className="text-3xl font-bold text-green-600">{result.statistics?.totalAssigned}</p>
            </div>
            <div className="stat-card">
              <p className="text-sm text-gray-600">Conflicts</p>
              <p className="text-3xl font-bold text-red-600">{result.statistics?.totalConflicts}</p>
            </div>
            <div className="stat-card">
              <p className="text-sm text-gray-600">On Time</p>
              <p className="text-3xl font-bold text-blue-600">{result.statistics?.scheduledOnTime}</p>
            </div>
            <div className="stat-card">
              <p className="text-sm text-gray-600">With Delay</p>
              <p className="text-3xl font-bold text-orange-600">{result.statistics?.scheduledWithDelay}</p>
            </div>
          </div>

          <div className="card">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Slot Allocations</h3>
            <div className="overflow-x-auto">
              <table className="table">
                <thead>
                  <tr>
                    <th>Tanker</th>
                    <th>Source</th>
                    <th>Hour</th>
                    <th>Duration</th>
                    <th>Priority</th>
                    <th>Delay</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {result.assignments?.map((assignment, idx) => (
                    <tr key={idx}>
                      <td className="font-medium">{assignment.tankerId}</td>
                      <td className="text-xs">{assignment.sourceId}</td>
                      <td>{assignment.hour}:00</td>
                      <td>{assignment.duration} hr</td>
                      <td>
                        <span className={`px-2 py-1 rounded text-xs ${
                          assignment.priority === 'critical' ? 'bg-red-100 text-red-800' :
                          assignment.priority === 'high' ? 'bg-orange-100 text-orange-800' :
                          assignment.priority === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                          'bg-green-100 text-green-800'
                        }`}>
                          {assignment.priority}
                        </span>
                      </td>
                      <td>{assignment.delay} hrs</td>
                      <td>
                        <span className={`px-2 py-1 rounded text-xs ${
                          assignment.delay === 0 ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'
                        }`}>
                          {assignment.delay === 0 ? 'On Time' : `Delayed ${assignment.delay}h`}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {result.conflicts?.length > 0 && (
            <div className="card border-red-200">
              <h3 className="text-lg font-semibold text-red-800 mb-4">Unresolved Conflicts</h3>
              <div className="space-y-2">
                {result.conflicts.map((conflict, idx) => (
                  <div key={idx} className="p-3 bg-red-50 rounded-lg">
                    <p className="text-sm font-medium text-red-800">{conflict.tankerId}</p>
                    <p className="text-xs text-red-600">{conflict.reason}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="card">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Algorithm Performance</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-3 bg-gray-50 rounded-lg">
                <p className="text-xs text-gray-500">Iterations</p>
                <p className="text-lg font-bold text-gray-800">{result.statistics?.iterations}</p>
              </div>
              <div className="p-3 bg-gray-50 rounded-lg">
                <p className="text-xs text-gray-500">Solutions Found</p>
                <p className="text-lg font-bold text-gray-800">{result.statistics?.solutionsFound}</p>
              </div>
              <div className="p-3 bg-gray-50 rounded-lg">
                <p className="text-xs text-gray-500">Avg Delay</p>
                <p className="text-lg font-bold text-gray-800">{result.statistics?.averageDelay} hrs</p>
              </div>
              <div className="p-3 bg-gray-50 rounded-lg">
                <p className="text-xs text-gray-500">Complexity</p>
                <p className="text-sm font-medium text-gray-800">{result.complexity?.time}</p>
              </div>
            </div>
          </div>

          {result.steps && (
            <div className="card">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">Backtracking Steps</h3>
              <div className="max-h-48 overflow-y-auto space-y-1">
                {result.steps.slice(0, 30).map((step, idx) => (
                  <div key={idx} className={`text-xs p-2 rounded ${
                    step.action?.includes('assigned') ? 'bg-green-50' :
                    step.action?.includes('conflict') ? 'bg-red-50' :
                    'bg-gray-50'
                  }`}>
                    <span className="font-medium">Step {step.step}:</span>{' '}
                    {step.tanker} → {step.action}
                    {step.delay !== undefined && ` (delay: ${step.delay}h)`}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default SlotAllocator;
