import React, { useState, useEffect } from 'react';

const API_BASE = 'http://localhost:5000/api';

function ResourceAssignment() {
  const [tankers, setTankers] = useState([]);
  const [areas, setAreas] = useState([]);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [tankersRes, areasRes] = await Promise.all([
        fetch(`${API_BASE}/tankers`),
        fetch(`${API_BASE}/areas`)
      ]);
      const [tankersData, areasData] = await Promise.all([
        tankersRes.json(),
        areasRes.json()
      ]);
      setTankers(tankersData);
      setAreas(areasData);
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  const runGreedy = async () => {
    setLoading(true);
    try {
      const availableTankers = tankers.filter(t => t.status === 'available');
      const response = await fetch(`${API_BASE}/algorithms/greedy`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tankers: availableTankers,
          areas: areas,
          options: { prioritizeDistance: true }
        })
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Error running greedy:', err);
    }
    setLoading(false);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-800">Resource Assignment</h1>
        <p className="text-gray-600 mt-1">Greedy Algorithm for Tanker Allocation</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-800">Available Tankers</h3>
            <span className="px-3 py-1 bg-green-100 text-green-800 rounded-full text-sm font-medium">
              {tankers.filter(t => t.status === 'available').length} available
            </span>
          </div>
          <div className="overflow-x-auto max-h-96">
            <table className="table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Type</th>
                  <th>Capacity</th>
                  <th>Location</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {tankers.map(tanker => (
                  <tr key={tanker.tankerId}>
                    <td className="font-medium">{tanker.tankerId}</td>
                    <td>
                      <span className={`px-2 py-1 rounded text-xs ${
                        tanker.type === 'large' ? 'bg-purple-100 text-purple-800' :
                        tanker.type === 'medium' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {tanker.type}
                      </span>
                    </td>
                    <td>{tanker.capacity.toLocaleString()} L</td>
                    <td className="text-xs">{tanker.currentLocation.lat.toFixed(2)}, {tanker.currentLocation.lng.toFixed(2)}</td>
                    <td>
                      <span className={`px-2 py-1 rounded text-xs ${
                        tanker.status === 'available' ? 'bg-green-100 text-green-800' :
                        tanker.status === 'en-route' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {tanker.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-800">Area Requests</h3>
            <span className="px-3 py-1 bg-orange-100 text-orange-800 rounded-full text-sm font-medium">
              {areas.length} areas
            </span>
          </div>
          <div className="overflow-x-auto max-h-96">
            <table className="table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Priority</th>
                  <th>Demand</th>
                  <th>Population</th>
                  <th>Congestion</th>
                </tr>
              </thead>
              <tbody>
                {areas.map(area => (
                  <tr key={area.areaId}>
                    <td className="font-medium">{area.name}</td>
                    <td>
                      <span className={`px-2 py-1 rounded text-xs ${
                        area.priority === 'critical' ? 'bg-red-100 text-red-800' :
                        area.priority === 'high' ? 'bg-orange-100 text-orange-800' :
                        area.priority === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-green-100 text-green-800'
                      }`}>
                        {area.priority}
                      </span>
                    </td>
                    <td>{area.demand.toLocaleString()} L</td>
                    <td>{area.population.toLocaleString()}</td>
                    <td>
                      <span className={`px-2 py-1 rounded text-xs ${
                        area.congestionLevel === 'severe' ? 'bg-red-100 text-red-800' :
                        area.congestionLevel === 'high' ? 'bg-orange-100 text-orange-800' :
                        area.congestionLevel === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-green-100 text-green-800'
                      }`}>
                        {area.congestionLevel}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="card">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-800">Run Greedy Algorithm</h3>
          <button
            onClick={runGreedy}
            disabled={loading}
            className="btn-success disabled:opacity-50"
          >
            {loading ? 'Assigning...' : 'Auto-Assign Tankers'}
          </button>
        </div>
        <p className="text-sm text-gray-600 mb-4">
          The greedy algorithm assigns tankers to areas based on priority, proximity, and capacity fit.
        </p>

        {result && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="p-3 bg-green-50 rounded-lg">
                <p className="text-sm text-green-600">Assigned</p>
                <p className="text-2xl font-bold text-green-800">{result.statistics?.totalAssigned}</p>
              </div>
              <div className="p-3 bg-red-50 rounded-lg">
                <p className="text-sm text-red-600">Unassigned</p>
                <p className="text-2xl font-bold text-red-800">{result.statistics?.totalUnassigned}</p>
              </div>
              <div className="p-3 bg-blue-50 rounded-lg">
                <p className="text-sm text-blue-600">Avg Efficiency</p>
                <p className="text-2xl font-bold text-blue-800">{result.statistics?.averageEfficiency}%</p>
              </div>
              <div className="p-3 bg-purple-50 rounded-lg">
                <p className="text-sm text-purple-600">Avg Distance</p>
                <p className="text-2xl font-bold text-purple-800">{result.statistics?.averageDistance} km</p>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="table">
                <thead>
                  <tr>
                    <th>Tanker</th>
                    <th>Assigned Area</th>
                    <th>Distance</th>
                    <th>Est. Time</th>
                    <th>Efficiency</th>
                    <th>Score</th>
                  </tr>
                </thead>
                <tbody>
                  {result.assignments?.map((assignment, idx) => (
                    <tr key={idx}>
                      <td className="font-medium">{assignment.tanker?.tankerId}</td>
                      <td>{assignment.area?.name}</td>
                      <td>{assignment.distance?.toFixed(2)} km</td>
                      <td>{assignment.estimatedTime} min</td>
                      <td>{assignment.efficiency}%</td>
                      <td>{assignment.score?.toFixed(0)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="p-3 bg-gray-50 rounded-lg">
              <p className="text-xs text-gray-500">
                <strong>Algorithm Complexity:</strong> {result.complexity?.time}
              </p>
              <p className="text-xs text-gray-500">
                <strong>Execution Time:</strong> {result.executionTime?.toFixed(2)} ms
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default ResourceAssignment;
