import React, { useState, useEffect } from 'react';
import { Line, Bar, Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const API_BASE = 'http://localhost:5000/api';

function Dashboard() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const response = await fetch(`${API_BASE}/analytics/dashboard`);
      const data = await response.json();
      setStats(data);
      setLoading(false);
    } catch (err) {
      setError('Failed to fetch dashboard data');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center text-red-500">
          <p className="text-xl">⚠️ {error}</p>
          <button onClick={fetchDashboardData} className="mt-4 btn-primary">
            Retry
          </button>
        </div>
      </div>
    );
  }

  const tankerChartData = {
    labels: ['Available', 'En Route', 'Maintenance'],
    datasets: [
      {
        data: [stats?.tankers?.available || 0, stats?.tankers?.enRoute || 0, stats?.tankers?.maintenance || 0],
        backgroundColor: ['#22c55e', '#3b82f6', '#ef4444'],
        borderWidth: 0,
      },
    ],
  };

  const deliveryChartData = {
    labels: ['Pending', 'Completed', 'Delayed'],
    datasets: [
      {
        data: [stats?.deliveries?.pending || 0, stats?.deliveries?.completed || 0, stats?.deliveries?.delayed || 0],
        backgroundColor: ['#f59e0b', '#22c55e', '#ef4444'],
        borderWidth: 0,
      },
    ],
  };

  const priorityChartData = {
    labels: ['Critical', 'High', 'Medium', 'Low'],
    datasets: [
      {
        label: 'Areas by Priority',
        data: [
          stats?.areas?.priority?.critical || 0,
          stats?.areas?.priority?.high || 0,
          stats?.areas?.priority?.medium || 0,
          stats?.areas?.priority?.low || 0
        ],
        backgroundColor: ['#dc2626', '#f97316', '#eab308', '#22c55e'],
        borderWidth: 0,
      },
    ],
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-800">Dashboard</h1>
          <p className="text-gray-600 mt-1">Water Tanker Distribution System - Karachi</p>
        </div>
        <div className="text-right">
          <p className="text-sm text-gray-500">Last Updated</p>
          <p className="font-medium">{new Date().toLocaleString()}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="stat-card bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-blue-100">Total Tankers</p>
              <p className="text-3xl font-bold mt-1">{stats?.tankers?.total || 0}</p>
            </div>
            <span className="text-4xl">🚛</span>
          </div>
          <div className="mt-4 text-sm text-blue-100">
            <span className="text-green-300">●</span> {stats?.tankers?.available || 0} available
          </div>
        </div>

        <div className="stat-card bg-gradient-to-br from-green-500 to-green-600 text-white">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-green-100">Total Areas</p>
              <p className="text-3xl font-bold mt-1">{stats?.areas?.total || 0}</p>
            </div>
            <span className="text-4xl">🏘️</span>
          </div>
          <div className="mt-4 text-sm text-green-100">
            <span className="text-yellow-300">●</span> {stats?.areas?.priority?.critical || 0} critical priority
          </div>
        </div>

        <div className="stat-card bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-purple-100">Deliveries</p>
              <p className="text-3xl font-bold mt-1">{stats?.deliveries?.total || 0}</p>
            </div>
            <span className="text-4xl">📦</span>
          </div>
          <div className="mt-4 text-sm text-purple-100">
            <span className="text-red-300">●</span> {stats?.deliveries?.delayed || 0} delayed
          </div>
        </div>

        <div className="stat-card bg-gradient-to-br from-orange-500 to-orange-600 text-white">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-orange-100">Water Sources</p>
              <p className="text-3xl font-bold mt-1">{stats?.sources?.total || 0}</p>
            </div>
            <span className="text-4xl">💧</span>
          </div>
          <div className="mt-4 text-sm text-orange-100">
            <span className="text-green-300">●</span> {stats?.sources?.operational || 0} operational
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Tanker Status</h3>
          <div className="h-64">
            <Doughnut
              data={tankerChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' }
                }
              }}
            />
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Delivery Status</h3>
          <div className="h-64">
            <Doughnut
              data={deliveryChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' }
                }
              }}
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Areas by Priority</h3>
          <div className="h-64">
            <Bar
              data={priorityChartData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { display: false }
                },
                scales: {
                  y: {
                    beginAtZero: true,
                    ticks: { stepSize: 1 }
                  }
                }
              }}
            />
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">System Capacity</h3>
          <div className="space-y-4 mt-4">
            <div>
              <div className="flex justify-between text-sm mb-1">
                <span className="text-gray-600">Tanker Utilization</span>
                <span className="font-medium">{stats?.tankers?.utilization || 0}%</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-3">
                <div
                  className="bg-blue-500 h-3 rounded-full transition-all duration-500"
                  style={{ width: `${stats?.tankers?.utilization || 0}%` }}
                ></div>
              </div>
            </div>
            <div>
              <div className="flex justify-between text-sm mb-1">
                <span className="text-gray-600">Supply/Demand Ratio</span>
                <span className="font-medium">{stats?.capacity?.supplyDemandRatio || 0}</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-3">
                <div
                  className="bg-green-500 h-3 rounded-full transition-all duration-500"
                  style={{ width: `${Math.min((stats?.capacity?.supplyDemandRatio || 0) * 50, 100)}%` }}
                ></div>
              </div>
            </div>
            <div>
              <div className="flex justify-between text-sm mb-1">
                <span className="text-gray-600">Delivery Completion Rate</span>
                <span className="font-medium">
                  {stats?.deliveries?.total > 0
                    ? ((stats?.deliveries?.completed / stats?.deliveries?.total) * 100).toFixed(1)
                    : 0}%
                </span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-3">
                <div
                  className="bg-purple-500 h-3 rounded-full transition-all duration-500"
                  style={{
                    width: `${
                      stats?.deliveries?.total > 0
                        ? (stats?.deliveries?.completed / stats?.deliveries?.total) * 100
                        : 0
                    }%`
                  }}
                ></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="card">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">Algorithm Performance</h3>
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <div className="text-center p-4 bg-blue-50 rounded-lg">
            <div className="text-2xl mb-2">🗺️</div>
            <p className="font-medium text-blue-800">Dijkstra</p>
            <p className="text-xs text-blue-600">Route Optimization</p>
            <p className="text-xs text-gray-500 mt-1">O((V+E) log V)</p>
          </div>
          <div className="text-center p-4 bg-green-50 rounded-lg">
            <div className="text-2xl mb-2">🎯</div>
            <p className="font-medium text-green-800">Greedy</p>
            <p className="text-xs text-green-600">Resource Assignment</p>
            <p className="text-xs text-gray-500 mt-1">O(n*m*log n)</p>
          </div>
          <div className="text-center p-4 bg-purple-50 rounded-lg">
            <div className="text-2xl mb-2">📅</div>
            <p className="font-medium text-purple-800">DP</p>
            <p className="text-xs text-purple-600">Scheduling</p>
            <p className="text-xs text-gray-500 mt-1">O(n*T*k)</p>
          </div>
          <div className="text-center p-4 bg-orange-50 rounded-lg">
            <div className="text-2xl mb-2">⏰</div>
            <p className="font-medium text-orange-800">Backtracking</p>
            <p className="text-xs text-orange-600">Slot Allocation</p>
            <p className="text-xs text-gray-500 mt-1">O(m^n)</p>
          </div>
          <div className="text-center p-4 bg-red-50 rounded-lg">
            <div className="text-2xl mb-2">💧</div>
            <p className="font-medium text-red-800">Ford-Fulkerson</p>
            <p className="text-xs text-red-600">Flow Optimization</p>
            <p className="text-xs text-gray-500 mt-1">O(E*max_flow)</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
