import React, { useState, useEffect } from 'react';

const API_BASE = 'http://localhost:5000/api';

function FlowOptimizer() {
  const [sources, setSources] = useState([]);
  const [areas, setAreas] = useState([]);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [sourcesRes, areasRes] = await Promise.all([
        fetch(`${API_BASE}/sources`),
        fetch(`${API_BASE}/areas`)
      ]);
      const [sourcesData, areasData] = await Promise.all([
        sourcesRes.json(),
        areasRes.json()
      ]);
      setSources(sourcesData);
      setAreas(areasData);
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  const buildFlowNetwork = () => {
    const edges = [];
    const superSource = 'SUPER_SOURCE';
    const superSink = 'SUPER_SINK';

    sources.forEach(source => {
      edges.push({
        from: superSource,
        to: source.sourceId,
        capacity: source.currentOutput / 1000,
        weight: 0
      });
    });

    sources.forEach(source => {
      areas.forEach(area => {
        if (area.nearestHydrants && area.nearestHydrants.length > 0) {
          const hydrant = area.nearestHydrants[0];
          const capacity = Math.min(source.currentOutput, area.demand) / 5000;
          if (capacity > 0) {
            edges.push({
              from: source.sourceId,
              to: hydrant,
              capacity: Math.floor(capacity) + 1,
              weight: 1
            });
          }
        }
      });
    });

    const hydrants = ['HYD-001', 'HYD-002', 'HYD-003', 'HYD-004', 'HYD-005', 'HYD-006', 'HYD-007', 'HYD-008', 'HYD-009', 'HYD-010'];
    hydrants.forEach(hydrant => {
      const connectedAreas = areas.filter(a => a.nearestHydrants?.includes(hydrant));
      connectedAreas.forEach(area => {
        edges.push({
          from: hydrant,
          to: area.areaId,
          capacity: Math.floor(area.demand / 10000) + 1,
          weight: 1
        });
      });
    });

    areas.forEach(area => {
      edges.push({
        from: area.areaId,
        to: superSink,
        capacity: Math.floor(area.demand / 5000) + 1,
        weight: 0
      });
    });

    return { edges };
  };

  const runFordFulkerson = async () => {
    setLoading(true);
    try {
      const graph = buildFlowNetwork();
      const response = await fetch(`${API_BASE}/algorithms/maxflow`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          graph: graph,
          source: 'SUPER_SOURCE',
          sink: 'SUPER_SINK'
        })
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Error running Ford-Fulkerson:', err);
    }
    setLoading(false);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-800">Flow Optimizer</h1>
        <p className="text-gray-600 mt-1">Ford-Fulkerson for Maximum Flow Distribution</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-800">Network Flow Diagram</h3>
            <button
              onClick={runFordFulkerson}
              disabled={loading}
              className="btn-success disabled:opacity-50"
            >
              {loading ? 'Calculating...' : 'Calculate Max Flow'}
            </button>
          </div>

          <div className="p-6 bg-gradient-to-br from-blue-50 to-cyan-50 rounded-xl">
            <div className="flex items-center justify-between mb-6">
              <div className="text-center">
                <div className="w-16 h-16 bg-blue-500 rounded-full flex items-center justify-center mx-auto mb-2">
                  <span className="text-white text-2xl">💧</span>
                </div>
                <p className="text-sm font-medium text-blue-800">Sources</p>
                <p className="text-xs text-blue-600">{sources.length}</p>
              </div>

              <div className="flex-1 mx-4">
                <div className="h-1 bg-gradient-to-r from-blue-500 via-purple-500 to-green-500 rounded"></div>
                <div className="flex justify-between mt-2 text-xs text-gray-500">
                  <span>Treatment Plants</span>
                  <span>Hydrants</span>
                  <span>Areas</span>
                </div>
              </div>

              <div className="text-center">
                <div className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center mx-auto mb-2">
                  <span className="text-white text-2xl">🏘️</span>
                </div>
                <p className="text-sm font-medium text-green-800">Areas</p>
                <p className="text-xs text-green-600">{areas.length}</p>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                {sources.slice(0, 4).map(source => (
                  <div key={source.sourceId} className="p-2 bg-white rounded-lg shadow-sm text-xs">
                    <p className="font-medium truncate">{source.name.split(' ').slice(0, 2).join(' ')}</p>
                    <p className="text-gray-500">{(source.currentOutput / 1000).toFixed(0)}k L/day</p>
                  </div>
                ))}
              </div>
              <div className="space-y-2">
                {['HYD-001', 'HYD-002', 'HYD-003', 'HYD-004'].map(hydrant => (
                  <div key={hydrant} className="p-2 bg-purple-100 rounded-lg shadow-sm text-xs text-center">
                    <p className="font-medium text-purple-800">{hydrant}</p>
                  </div>
                ))}
              </div>
              <div className="space-y-2">
                {areas.slice(0, 4).map(area => (
                  <div key={area.areaId} className="p-2 bg-white rounded-lg shadow-sm text-xs">
                    <p className="font-medium truncate">{area.name}</p>
                    <p className="text-gray-500">{(area.demand / 1000).toFixed(0)}k L/day</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Network Statistics</h3>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Total Sources</label>
              <p className="text-2xl font-bold text-blue-600">{sources.length}</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Total Areas</label>
              <p className="text-2xl font-bold text-green-600">{areas.length}</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Total Capacity</label>
              <p className="text-lg font-medium text-gray-600">
                {sources.reduce((sum, s) => sum + s.currentOutput, 0).toLocaleString()} L/day
              </p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Total Demand</label>
              <p className="text-lg font-medium text-gray-600">
                {areas.reduce((sum, a) => sum + a.demand, 0).toLocaleString()} L/day
              </p>
            </div>
          </div>

          {result && (
            <div className="mt-6 p-4 bg-gray-50 rounded-lg">
              <p className="text-xs text-gray-500">
                <strong>Complexity:</strong> {result.complexity?.time}
              </p>
              <p className="text-xs text-gray-500">
                <strong>Execution Time:</strong> {result.executionTime?.toFixed(2)} ms
              </p>
            </div>
          )}
        </div>
      </div>

      {result && (
        <div className="space-y-6">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="stat-card bg-gradient-to-br from-blue-500 to-blue-600 text-white">
              <p className="text-blue-100">Max Flow</p>
              <p className="text-3xl font-bold mt-1">{result.maxFlow}</p>
              <p className="text-xs text-blue-200 mt-1">units/day</p>
            </div>
            <div className="stat-card bg-gradient-to-br from-green-500 to-green-600 text-white">
              <p className="text-green-100">Iterations</p>
              <p className="text-3xl font-bold mt-1">{result.statistics?.iterations}</p>
              <p className="text-xs text-green-200 mt-1">BFS runs</p>
            </div>
            <div className="stat-card bg-gradient-to-br from-purple-500 to-purple-600 text-white">
              <p className="text-purple-100">Edges with Flow</p>
              <p className="text-3xl font-bold mt-1">{result.statistics?.edgesWithFlow}</p>
              <p className="text-xs text-purple-200 mt-1">active paths</p>
            </div>
            <div className="stat-card bg-gradient-to-br from-orange-500 to-orange-600 text-white">
              <p className="text-orange-100">Avg Utilization</p>
              <p className="text-3xl font-bold mt-1">{result.statistics?.avgUtilization}%</p>
              <p className="text-xs text-orange-200 mt-1">network load</p>
            </div>
          </div>

          <div className="card">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Flow Distribution</h3>
            <div className="overflow-x-auto">
              <table className="table">
                <thead>
                  <tr>
                    <th>From</th>
                    <th>To</th>
                    <th>Flow</th>
                    <th>Capacity</th>
                    <th>Utilization</th>
                  </tr>
                </thead>
                <tbody>
                  {result.flowDistribution?.slice(0, 20).map((flow, idx) => (
                    <tr key={idx}>
                      <td className="font-medium text-xs">{flow.from}</td>
                      <td className="text-xs">{flow.to}</td>
                      <td>{flow.flow}</td>
                      <td>{flow.capacity}</td>
                      <td>
                        <div className="flex items-center gap-2">
                          <div className="w-24 bg-gray-200 rounded-full h-2">
                            <div
                              className={`h-2 rounded-full ${
                                parseFloat(flow.utilization) > 80 ? 'bg-red-500' :
                                parseFloat(flow.utilization) > 50 ? 'bg-yellow-500' :
                                'bg-green-500'
                              }`}
                              style={{ width: `${Math.min(parseFloat(flow.utilization), 100)}%` }}
                            ></div>
                          </div>
                          <span className="text-xs">{flow.utilization}%</span>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {result.steps && (
            <div className="card">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">Augmenting Paths Found</h3>
              <div className="max-h-48 overflow-y-auto space-y-2">
                {result.steps.map((step, idx) => (
                  <div key={idx} className="p-3 bg-gray-50 rounded-lg">
                    <div className="flex justify-between items-center">
                      <span className="text-sm font-medium">Iteration {step.iteration}</span>
                      <span className="text-xs text-gray-500">
                        Bottleneck: {step.bottleneck} | Total: {step.totalFlow}
                      </span>
                    </div>
                    <div className="flex flex-wrap gap-1 mt-2">
                      {step.path.map((pathStep, pIdx) => (
                        <span key={pIdx} className="px-2 py-1 bg-blue-100 text-blue-800 rounded text-xs">
                          {pathStep}
                        </span>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default FlowOptimizer;
