import React, { useState, useEffect } from 'react';

const API_BASE = 'http://localhost:5000/api';

function Scheduler() {
  const [tankers, setTankers] = useState([]);
  const [areas, setAreas] = useState([]);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [deliveries, setDeliveries] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [tankersRes, areasRes] = await Promise.all([
        fetch(`${API_BASE}/tankers`),
        fetch(`${API_BASE}/areas`)
      ]);
      const [tankersData, areasData] = await Promise.all([
        tankersRes.json(),
        areasRes.json()
      ]);
      setTankers(tankersData);
      setAreas(areasData);

      const sampleDeliveries = [];
      for (let i = 0; i < 15; i++) {
        const area = areasData[Math.floor(Math.random() * areasData.length)];
        sampleDeliveries.push({
          deliveryId: `DEL-${String(i + 1).padStart(3, '0')}`,
          scheduledHour: 6 + Math.floor(Math.random() * 12),
          loadAmount: 2000 + Math.floor(Math.random() * 8000),
          priority: ['critical', 'high', 'medium', 'low'][Math.floor(Math.random() * 4)],
          areaName: area.name
        });
      }
      setDeliveries(sampleDeliveries);
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  const runDP = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${API_BASE}/algorithms/dp-schedule`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          deliveries: deliveries,
          tankerCount: Math.min(tankers.length, 10),
          timeSlots: 14
        })
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Error running DP:', err);
    }
    setLoading(false);
  };

  const hours = Array.from({ length: 14 }, (_, i) => 6 + i);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-800">Delivery Scheduler</h1>
        <p className="text-gray-600 mt-1">Dynamic Programming for Optimal Scheduling</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-800">Scheduled Deliveries</h3>
            <button
              onClick={runDP}
              disabled={loading}
              className="btn-primary disabled:opacity-50"
            >
              {loading ? 'Optimizing...' : 'Run DP Optimizer'}
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Area</th>
                  <th>Priority</th>
                  <th>Load</th>
                  <th>Scheduled Hour</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {deliveries.map(delivery => (
                  <tr key={delivery.deliveryId}>
                    <td className="font-medium">{delivery.deliveryId}</td>
                    <td>{delivery.areaName}</td>
                    <td>
                      <span className={`px-2 py-1 rounded text-xs ${
                        delivery.priority === 'critical' ? 'bg-red-100 text-red-800' :
                        delivery.priority === 'high' ? 'bg-orange-100 text-orange-800' :
                        delivery.priority === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-green-100 text-green-800'
                      }`}>
                        {delivery.priority}
                      </span>
                    </td>
                    <td>{delivery.loadAmount.toLocaleString()} L</td>
                    <td>{delivery.scheduledHour}:00</td>
                    <td>
                      <span className="px-2 py-1 rounded text-xs bg-blue-100 text-blue-800">
                        pending
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Schedule Parameters</h3>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Available Tankers</label>
              <p className="text-2xl font-bold text-blue-600">{tankers.length}</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Total Deliveries</label>
              <p className="text-2xl font-bold text-green-600">{deliveries.length}</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Time Window</label>
              <p className="text-lg font-medium text-gray-600">06:00 - 20:00</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Slot Duration</label>
              <p className="text-lg font-medium text-gray-600">1 hour</p>
            </div>
          </div>

          {result && (
            <div className="mt-6 p-4 bg-gray-50 rounded-lg">
              <p className="text-xs text-gray-500">
                <strong>Algorithm Complexity:</strong> {result.complexity?.time}
              </p>
              <p className="text-xs text-gray-500">
                <strong>Execution Time:</strong> {result.executionTime?.toFixed(2)} ms
              </p>
            </div>
          )}
        </div>
      </div>

      {result && (
        <div className="space-y-6">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="stat-card">
              <p className="text-sm text-gray-600">Scheduled</p>
              <p className="text-3xl font-bold text-green-600">{result.statistics?.totalScheduled}</p>
            </div>
            <div className="stat-card">
              <p className="text-sm text-gray-600">Unscheduled</p>
              <p className="text-3xl font-bold text-red-600">{result.statistics?.unscheduled}</p>
            </div>
            <div className="stat-card">
              <p className="text-sm text-gray-600">Total Delay</p>
              <p className="text-3xl font-bold text-orange-600">{result.statistics?.totalDelaySlots} hrs</p>
            </div>
            <div className="stat-card">
              <p className="text-sm text-gray-600">Avg Delay Cost</p>
              <p className="text-3xl font-bold text-purple-600">${result.statistics?.totalDelayCost}</p>
            </div>
          </div>

          <div className="card">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Optimized Schedule Timeline</h3>
            <div className="overflow-x-auto">
              <div className="min-w-[800px]">
                <div className="grid grid-cols-[100px_repeat(14,1fr)] gap-1">
                  <div className="p-2 text-xs font-medium text-gray-500">Tanker</div>
                  {hours.map(hour => (
                    <div key={hour} className="p-2 text-xs font-medium text-gray-500 text-center">
                      {hour}:00
                    </div>
                  ))}

                  {Array.from({ length: Math.min(10, result.schedule?.length || 0) }, (_, tankerIdx) => (
                    <React.Fragment key={tankerIdx}>
                      <div className="p-2 text-xs font-medium text-gray-700">
                        TK-{String(tankerIdx + 1).padStart(3, '0')}
                      </div>
                      {hours.map(hour => {
                        const assignment = result.schedule?.find(
                          a => a.tanker === tankerIdx + 1 && a.startTime <= hour && a.endTime > hour
                        );
                        return (
                          <div
                            key={hour}
                            className={`p-1 rounded text-xs text-center ${
                              assignment
                                ? assignment.delay === 0
                                  ? 'bg-green-200 text-green-800'
                                  : 'bg-yellow-200 text-yellow-800'
                                : 'bg-gray-100'
                            }`}
                          >
                            {assignment ? `${assignment.deliveryId.substring(4)}` : ''}
                          </div>
                        );
                      })}
                    </React.Fragment>
                  ))}
                </div>
              </div>
              <div className="flex gap-4 mt-4 text-xs">
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 bg-green-200 rounded"></div>
                  <span>On Time</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 bg-yellow-200 rounded"></div>
                  <span>Delayed</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-4 h-4 bg-gray-100 rounded"></div>
                  <span>Available</span>
                </div>
              </div>
            </div>
          </div>

          <div className="card">
            <h3 className="text-lg font-semibold text-gray-800 mb-4">Optimized Assignments</h3>
            <div className="overflow-x-auto">
              <table className="table">
                <thead>
                  <tr>
                    <th>Delivery</th>
                    <th>Tanker</th>
                    <th>Slot</th>
                    <th>Delay</th>
                    <th>Delay Cost</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {result.schedule?.map((assignment, idx) => (
                    <tr key={idx}>
                      <td className="font-medium">{assignment.deliveryId}</td>
                      <td>TK-{String(assignment.tanker).padStart(3, '0')}</td>
                      <td>{assignment.timeLabel}</td>
                      <td>{assignment.delay} hrs</td>
                      <td>${assignment.delayCost}</td>
                      <td>
                        <span className={`px-2 py-1 rounded text-xs ${
                          assignment.delay === 0 ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'
                        }`}>
                          {assignment.delay === 0 ? 'On Time' : 'Delayed'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {result.steps && (
            <div className="card">
              <h3 className="text-lg font-semibold text-gray-800 mb-4">DP Algorithm Steps</h3>
              <div className="max-h-48 overflow-y-auto space-y-2">
                {result.steps.map((step, idx) => (
                  <div key={idx} className="text-xs p-2 bg-gray-50 rounded flex justify-between">
                    <span>
                      <strong>Step {step.step}:</strong> Processing {step.delivery}
                    </span>
                    <span className="text-gray-500">
                      Priority: {step.priority} | Cost: {step.bestCost}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default Scheduler;
